<template><div class="app-container"><el-alert title="默认口径：完成/入库计业绩，退款和退回在发生日记负数，区域与团队使用业务快照，金额不含运费；健康统计少于10人不展示。" type="info" :closable="false" style="margin-bottom:16px"/><div class="filter-container"><el-date-picker v-model="dates" type="daterange" value-format="yyyy-MM-dd" start-placeholder="开始日期" end-placeholder="结束日期"/><el-button type="primary" @click="load">刷新全部</el-button><el-date-picker v-model="runDate" type="date" value-format="yyyy-MM-dd" placeholder="汇总日期"/><el-button @click="runDaily">运行日报汇总</el-button></div><el-tabs v-model="tab"><el-tab-pane label="区域业绩" name="region"><el-table :data="region" border><el-table-column prop="dimensionCode" label="区域"/><el-table-column prop="metricCode" label="指标"/><el-table-column prop="amount" label="金额"/><el-table-column prop="count" label="数量"/></el-table></el-tab-pane><el-tab-pane label="库存库龄" name="stock"><el-table :data="stock" border><el-table-column prop="accountName" label="库存账户"/><el-table-column prop="regionCode" label="区域"/><el-table-column prop="productName" label="商品"/><el-table-column prop="productId" label="商品ID"/><el-table-column prop="availableQty" label="库存"/><el-table-column prop="maxAgeDays" label="最大库龄"/><el-table-column prop="noOutboundDays" label="无出库天数"/><el-table-column prop="agingLevel" label="风险"/><el-table-column prop="inventoryCost" label="库存成本"/></el-table></el-tab-pane><el-tab-pane label="库存账批次账对账" name="stockReconcile"><el-table :data="stockReconcile" border><el-table-column prop="accountName" label="库存账户"/><el-table-column prop="regionCode" label="区域"/><el-table-column prop="productName" label="商品"/><el-table-column prop="skuId" label="SKU_ID"/><el-table-column prop="totalAvailableQty" label="总账可用"/><el-table-column prop="batchAvailableQty" label="批次可用"/><el-table-column prop="availableDifference" label="可用差异"/><el-table-column prop="totalFrozenQty" label="总账冻结"/><el-table-column prop="batchFrozenQty" label="批次冻结"/><el-table-column prop="frozenDifference" label="冻结差异"/><el-table-column prop="reconcileStatus" label="状态"/></el-table></el-tab-pane><el-tab-pane label="财务对账" name="finance"><el-descriptions :column="3" border><el-descriptions-item v-for="(v,k) in finance" :key="k" :label="k">{{v}}</el-descriptions-item></el-descriptions></el-tab-pane><el-tab-pane label="匿名健康汇总" name="health"><el-table :data="health" border><el-table-column prop="regionCode" label="区域"/><el-table-column prop="dataType" label="类型"/><el-table-column prop="userCount" label="用户数"/><el-table-column prop="recordCount" label="记录数"/><el-table-column prop="averageValue" label="均值"/><el-table-column prop="alertCount" label="预警数"/><el-table-column prop="suppressed" label="小样本抑制"/></el-table></el-tab-pane></el-tabs></div></template><script>import{getJkRegionReport,getJkInventoryAgingReport,getJkInventoryReconcileReport,getJkFinanceReport,getJkHealthAnonymousReport,runJkReportDaily}from'@/api/jkBusiness';export default{data(){return{dates:[],runDate:'',tab:'region',region:[],stock:[],stockReconcile:[],finance:{},health:[]}},created(){this.load()},methods:{params(){return{startDate:this.dates&&this.dates[0],endDate:this.dates&&this.dates[1]}},data(r){return(r&&r.data)||r||[]},load(){const p=this.params();getJkRegionReport(p).then(r=>this.region=this.data(r));getJkInventoryAgingReport({warnDays:60,seriousDays:90}).then(r=>this.stock=this.data(r));getJkInventoryReconcileReport({onlyMismatch:true}).then(r=>this.stockReconcile=this.data(r));getJkFinanceReport(p).then(r=>this.finance=this.data(r));getJkHealthAnonymousReport({...p,minSampleSize:10}).then(r=>this.health=this.data(r))},runDaily(){if(!this.runDate)return this.$message.warning('请选择汇总日期');runJkReportDaily({metricDate:this.runDate}).then(r=>{this.$message.success('汇总完成，写入 '+((r&&r.data)||0)+' 个指标');this.load()})}}}</script>
